function picCircle(cx: number, cy: number, r: number, n: number = 16): [number, number][] {
  const p: [number, number][] = [];
  for (let i = 0; i <= n; i++) {
    const a = (i / n) * Math.PI * 2;
    p.push([cx + r * Math.cos(a), cy + r * Math.sin(a)]);
  }
  return p;
}

function picLine(x1: number, y1: number, x2: number, y2: number): [number, number][] {
  return [[x1, y1], [x2, y2]];
}

function picRect(x: number, y: number, w: number, h: number): [number, number][] {
  return [[x, y], [x + w, y], [x + w, y + h], [x, y + h], [x, y]];
}

function picTri(...pts: [number, number][]): [number, number][] {
  return [...pts, pts[0]];
}

